import{_ as t,o as e,c as a,a4 as u}from"./chunks/framework.9tZL7ZIQ.js";const _=JSON.parse('{"title":"1973年 · 风暴前的布局","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1973年.md","filePath":"05_quotes/by-year/1973年.md"}'),q={name:"05_quotes/by-year/1973年.md"};function l(r,o,c,b,p,i){return e(),a("div",null,[...o[0]||(o[0]=[u('<h1 id="_1973年-·-风暴前的布局" tabindex="-1">1973年 · 风暴前的布局 <a class="header-anchor" href="#_1973年-·-风暴前的布局" aria-label="Permalink to &quot;1973年 · 风暴前的布局&quot;">​</a></h1><blockquote><p>&quot;我们预计，该组合长期将带来稳健的收益。&quot;——巴菲特（42岁）</p></blockquote><p>本页收录1973年致股东信中的经典语录。ROE从19.8%回落至17.4%，股票组合出现超1200万美元未实现亏损。但就在这一年，巴菲特开启了对华盛顿邮报的大手笔投资，并宣布&quot;永久持有&quot;——这是伯克希尔历史上第一次明确这一策略，标志着从&quot;困境转型&quot;走向&quot;长期投资&quot;的战略升级。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;我们预计，该组合长期将带来稳健的收益。&quot;（论股票组合1200万美元未实现亏损）</p></blockquote><blockquote><p>&quot;按成本价计量的普通股组合，从企业内在价值来看具备良好的投资价值。&quot;</p></blockquote><blockquote><p>&quot;我们从未设想过，1973年会是灾难性的保险亏损年份——但我们确实预料到了承保利润率的显著恶化。&quot;</p></blockquote><blockquote><p>&quot;价格管制或许削平了行业上行期的盈利峰值，却无法避免行业下行期必然到来的利润低谷。&quot;（论纺织业务）</p></blockquote><blockquote><p>&quot;家庭与汽车保险公司在芝加哥地区的承保业绩极差。核心问题在于：驾驶里程减少可能带来的事故发生率下降，能否抵消医疗、车辆维修成本以及陪审团判决赔偿金额持续通胀带来的影响。我们认为，通胀带来的负面影响，将远超驾驶减少带来的利好。&quot;</p></blockquote><blockquote><p>&quot;我们&quot;罗克福德领先银行&quot;的地位进一步巩固。但当前利率结构、美联储新收款规则导致可投资资金减少，使得伊利诺伊国民银行1973年收益很难实现增长。&quot;</p></blockquote><blockquote><p>&quot;三位最重要的子公司——国民赔偿保险、伊利诺伊国民银行、家庭与汽车保险公司——全部是创始人型企业家。&quot;</p></blockquote><blockquote><p>&quot;管理层的长期目标是：在坚持稳健的会计政策与债务政策的前提下，实现长期平均资本回报率略高于美国工业企业的整体水平。&quot;</p></blockquote><blockquote><p>&quot;尽管收益有所增长，但收益的增长幅度未能匹配股东投入资本的增幅。&quot;</p></blockquote><blockquote><p>&quot;我们预计，未来蓝筹印花公司将实现与投入资本相匹配的稳健收益，尽管其收益水平必然远低于交易印花业务维持在历史高位时可实现的规模。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><h2 id="_1973年是转折前的最后宁静之年。roe从19-8-回落至17-4-保险承保利润率开始恶化-股市大跌带来1200万美元未实现亏损。但同年-伯克希尔完成与多元零售公司的合并-间接持有蓝筹印花16-股权-资本版图持续扩张。巴菲特更在这一年大规模增持华盛顿邮报-首次宣布-计划永久持有-——这笔投资最终持有超过40年-收益率超过百倍。" tabindex="-1">1973年是转折前的最后宁静之年。ROE从19.8%回落至17.4%，保险承保利润率开始恶化，股市大跌带来1200万美元未实现亏损。但同年，伯克希尔完成与多元零售公司的合并，间接持有蓝筹印花16%股权，资本版图持续扩张。巴菲特更在这一年大规模增持华盛顿邮报，首次宣布&quot;计划永久持有&quot;——这笔投资最终持有超过40年，收益率超过百倍。 <a class="header-anchor" href="#_1973年是转折前的最后宁静之年。roe从19-8-回落至17-4-保险承保利润率开始恶化-股市大跌带来1200万美元未实现亏损。但同年-伯克希尔完成与多元零售公司的合并-间接持有蓝筹印花16-股权-资本版图持续扩张。巴菲特更在这一年大规模增持华盛顿邮报-首次宣布-计划永久持有-——这笔投资最终持有超过40年-收益率超过百倍。" aria-label="Permalink to &quot;1973年是转折前的最后宁静之年。ROE从19.8%回落至17.4%，保险承保利润率开始恶化，股市大跌带来1200万美元未实现亏损。但同年，伯克希尔完成与多元零售公司的合并，间接持有蓝筹印花16%股权，资本版图持续扩张。巴菲特更在这一年大规模增持华盛顿邮报，首次宣布&quot;计划永久持有&quot;——这笔投资最终持有超过40年，收益率超过百倍。&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1973年/翻译">/01_letters/1973年/翻译</a></li></ul>',20)])])}const n=t(q,[["render",l]]);export{_ as __pageData,n as default};
